import {reporterWait} from "../core/reporter-question.ts";
import {z} from 'zod';
import {ServiceBase} from './service.ts';
import {IssueService} from './issues.ts';
import {currentJobRevision} from '../core/current-job-input.ts';
import type {Issue,Job} from '../core/types.ts';
import type {ProcessingWait} from '../domain/processing.ts';

/** Questions are already generated by the Agent; publication never invokes another model. */
export class ReporterInquiryService extends ServiceBase {
 async ask(id:string):Promise<{url?:string;error?:string}> {
  const lock=`reporter:${id}`;
  if(this.deps.publicationLocks.has(lock))return {error:'正在向报告者提问，请等待发布结果。'};
  this.deps.publicationLocks.add(lock);
  try{return await this.send(id);}finally{this.deps.publicationLocks.delete(lock);}
 }
 private async send(id:string):Promise<{url?:string;error?:string}>{
  const job=this.job(id),issue=this.store.get<Issue>('issues',job.issueId)!;
  const wait=issue?.processing?.waits.find(w=>w.requestedByRunId===id&&reporterWait(w));
  if(job.reporterInquiry?.status==='published')return {url:job.reporterInquiry.url};
  if(!issue||issue.type!=='issue'||issue.state!=='open'||job.status!=='waiting_input'||!['triage','investigate'].includes(job.kind)||job.caseId!==issue.processing?.id||!wait)throw Error('当前任务没有可向报告者发送的事实问题。');
  const repo=this.repo(job.repoId),name=repo.githubName??(repo.mode==='github'?repo.fullName:undefined);
  if(!name)throw Error('此事项没有关联 GitHub Issue，无法向报告者提问。');
  const questions=wait.questions!.map(q=>q.question),marker=`<!-- maintainer-workbench:reporter:${job.id}:${wait.id} -->`;
  const prior=job.reporterInquiry;
  const body=prior?.waitId===wait.id?prior.body:`@${issue.author} 为了继续定位这个问题，请补充以下信息：\n\n${questions.map((q,i)=>`${i+1}. ${q}`).join('\n')}\n\n请直接在本 Issue 回复；暂时无法提供的项目也请说明。日志、截图和样例文件请先移除密钥及个人敏感信息。\n\n${marker}`;
  const stamp=JSON.stringify(wait.questions);
  const assertCurrent=()=>{
   const current=this.store.get<Issue>('issues',issue.id),saved=this.job(id);
   const active=current?.processing?.waits.find(w=>w.id===wait.id);
   if(!current||current.state!=='open'||saved.status!=='waiting_input'||current.processing?.id!==job.caseId||!active||!reporterWait(active)||JSON.stringify(active.questions)!==stamp||saved.revision!==currentJobRevision(saved,current,this.repo(repo.id),this.store.jobs()))throw Error('事项版本或提问内容已变化，已停止发布；请重新核对。');
  };
  this.saveJob({...job,reporterInquiry:{waitId:wait.id,status:'publishing',body,startedAt:prior?.startedAt??new Date().toISOString()}});
  try{
   assertCurrent();
   let posted:{html_url:string;created_at?:string}|undefined;
   for(let page=1;;page++){
    const rows=z.array(z.object({body:z.string().nullable(),html_url:z.string().url(),created_at:z.string().optional()})).parse(await this.github.request(`/repos/${name}/issues/${issue.number}/comments?per_page=100&page=${page}`));
    posted=rows.find(r=>r.body?.includes(marker));if(posted||rows.length<100)break;
   }
   if(!posted){
    const live=z.object({updated_at:z.string()}).parse(await this.github.request(`/repos/${name}/issues/${issue.number}`));
    if(live.updated_at!==issue.updatedAt)throw Error('Issue 已有新动态，请先同步仓库后再发送问题。');
    assertCurrent();
    posted=z.object({html_url:z.string().url(),created_at:z.string().optional()}).parse(await this.github.request(`/repos/${name}/issues/${issue.number}/comments`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({body})},assertCurrent));
   }
   const confirmed=z.object({updated_at:z.string()}).parse(await this.github.request(`/repos/${name}/issues/${issue.number}`));
   this.store.transaction(()=>{
    assertCurrent();
    const request=new IssueService(this.deps).askInformation(issue.id,questions,issue.author,posted!.created_at??this.job(id).reporterInquiry!.startedAt,{id:`reporter:${job.id}:${wait.id}`,url:posted!.html_url});
    this.store.processing.dispatch(issue.id,{type:'wait.cancelled',waitId:wait.id,reason:'问题已发布到 Issue，由报告者补充资料'},'system',`reporter-published:${wait.id}`);
    this.saveJob({...this.job(id),status:'completed',reporterInquiry:{...this.job(id).reporterInquiry!,status:'published',url:posted!.html_url,requestId:request.id,remoteUpdatedAt:confirmed.updated_at}});
    this.store.audit('reporter.question_published',posted!.html_url,id);
   });
   return {url:posted.html_url};
  }catch(error){
   const message=error instanceof Error?error.message:String(error);
   this.saveJob({...this.job(id),reporterInquiry:{...this.job(id).reporterInquiry!,status:'failed',error:message}});
   this.store.audit('reporter.question_failed',message,id);
   return {error:message};
  }
 }
}
